import{_ as a,o,c as t,a2 as l}from"./chunks/framework.B0p3fmqd.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"moneywash/changelog.md","filePath":"moneywash/changelog.md","lastUpdated":1791039789000}'),n={name:"moneywash/changelog.md"};function i(d,e,s,r,h,c){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_5-1-0" tabindex="-1">5.1.0 <a class="header-anchor" href="#_5-1-0" aria-label="Permalink to &quot;5.1.0&quot;">​</a></h2><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li><code>Config.MaxNoteWorth</code>: the most a single dirty money item can wash for.</li><li>Tokens can be added to the shop from the crafting spot as well as the boss menu.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Dirty money with no stamped value defaults to $1 per item. It used to be a random 100 to 5000.</li><li><code>Config.UseMetadataWorth</code> is on by default.</li><li>The token recipe uses standard inventory items.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A finished wash can only be collected once.</li><li>The amount to wash is validated, and money is valued lowest first so a large item cannot be washed repeatedly.</li></ul><div class="warning custom-block"><p class="custom-block-title">Updating</p><p>Config files are replaced when you update. If you edited <code>config.lua</code>, merge your values into the new file. Servers still on a <code>BlackMoneyWorth</code> of 100 to 5000 should change it to <code>{ min = 1, max = 1 }</code>.</p></div>',9)])])}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
